from taf.collectors.ttitrace_snapshot_airphone.factory import TtiTraceSnapshotAirphoneFactory
from taf.collectors.core import core
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ttitrace_snapshot_airphone(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_ttitrace_snapshot_airphone_collector(self,
                                                    name,
                                                    executor,
                                                    container=None,
                                                    script_path=None,
                                                    log_dir=None,
                                                    target_file_name=None,
                                                    start_timeout=None,
                                                    stop_timeout=None):

        """
        Create a collector for TTI trace *.bin files (snapshot mode) on AirPhone.

        :param str name: name of collector
        :param dict executor: setup info like host, user, password, proxy and port,in dict format
        :param str container: (optional) container name substring, default: 'L2RT'
        :param str script_path: (optional) path on the AirPhone where we can find the ttitrace snapshot script,
                                default: "/opt/nokia/tools/eventsTraceCollector/eventsCollect.sh"
        :param str log_dir: (optional) path on the AirPhone where we can find the ttitrace snapshot bin files,
                                default: "/var/eventsTrace"
        :param str target_file_name: (optional) file name part of the path under which the ttitrace snapshot
                                     zip file is stored locally during collect_collectors,
                                     default: "{name}.tgz", where "{name}" corresponds to the "name" parameter
                                     for this keyword
        :param float start_timeout: (optional) start timeout is the time to wait after starting the process for the
                                    "mkdir:" or "Small file. Ignoring..." message, as a float, default value: "10.0"
        :param float stop_timeout: (optional)  stop timeout is the time to wait after sending CTRL-C for the process
                                   to terminate, as a float, default value: "3.0"
        """

        configuration = {'name': name}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["executor", "script_path", "log_dir", "target_file_name",
                                  "start_timeout", "stop_timeout", "container"]:
                if parameter_value is not None:
                    configuration[parameter_name] = float(parameter_value) \
                        if parameter_name in ["start_timeout", "stop_timeout"] else parameter_value
        logger.info("Creating Ttitrace Snapshot Airphone Collector with alias name :" + name)
        ttitrace_snapshot_airphone = TtiTraceSnapshotAirphoneFactory().create(configuration=configuration,
                                                                              existing_arguments={})
        logger.info("Ttitrace Snapshot Airphone Collector created successfully")
        self.set_alias(name, ttitrace_snapshot_airphone)
